//! The TypeScript text of `web/src/gen/api.ts`, a pure function of the
//! registry. Every name and path in the registry is ASCII, and every
//! string goes through [`ts_str`], so no registry text can end a literal.

use fstp_access::{Classification, Method, OpSpec, Scope, SessionNeed, Shape, route_params};

/// The header of the generated file.
const HEADER: &str = "\
// Operation types, the operation table, route segments and structural
// validators, generated from the OPS registry of fstp-access by
// tools/gen-ts (M4 design sections 1.1 and 3.9, ADR-014).
//
// Do not edit this file. Regenerate it with
//   cargo run -p gen-ts -- --root .
// CI checks it with
//   cargo run -p gen-ts -- --check --root .
//
// Paths are relative to API_PREFIX, except the public pages (base \"page\"),
// which are served at their own path with no script.
//
// SCHEMAS holds the reply shape of each operation whose data the API core
// serves, from the REPLIES table of fstp-access. VALIDATORS holds one
// structural validator per entry. Objects are closed, and an amount is an
// ADR-006 EUR string, never a JSON number.
";

/// The imports of the generated file: the ADR-006 amount reader, so the
/// validators judge amounts exactly as the pages read them.
const IMPORTS: &str = "import { parseAmount } from \"../core/money.js\";\n";

/// The schema types and the validators over `SCHEMAS` (design sections
/// 3.7 and 3.9). `fitsSchema` refuses members an object shape does not
/// name, as the server's decoders do.
const SCHEMA_TYPES: &str = r#"
/** The structure of one JSON value of a reply. */
export type Schema =
  | { readonly kind: "string" }
  | { readonly kind: "id" }
  | { readonly kind: "amount" }
  | { readonly kind: "bool" }
  | { readonly kind: "int" }
  | { readonly kind: "null" }
  | { readonly kind: "enum"; readonly values: readonly string[] }
  | { readonly kind: "array"; readonly items: Schema }
  | { readonly kind: "nullable"; readonly inner: Schema }
  | { readonly kind: "object"; readonly fields: Readonly<Record<string, SchemaField>> };

/** One member of an object schema. */
export interface SchemaField {
  readonly schema: Schema;
  readonly optional: boolean;
}
"#;

/// The structural validators, after `SCHEMAS`.
const VALIDATOR_TAIL: &str = r#"
/** Whether `v` is a plain object parsed from JSON. */
function isPlainObject(v: unknown): v is Readonly<Record<string, unknown>> {
  return typeof v === "object" && v !== null && !Array.isArray(v) && Object.getPrototypeOf(v) === Object.prototype;
}

/** Whether `o` has `k` as its own member. */
function hasOwn(o: object, k: string): boolean {
  return Object.prototype.hasOwnProperty.call(o, k);
}

/**
 * Whether `v`, a value from `JSON.parse`, fits `s`. Objects are closed:
 * a member `s` does not name is refused, and a missing member passes only
 * when it is optional. An id is a non-empty string, an int a safe
 * integer, and an amount an ADR-006 EUR string. It never throws.
 */
export function fitsSchema(s: Schema, v: unknown): boolean {
  switch (s.kind) {
    case "string":
      return typeof v === "string";
    case "id":
      return typeof v === "string" && v !== "";
    case "amount":
      return parseAmount(v, "EUR").ok;
    case "bool":
      return typeof v === "boolean";
    case "int":
      return typeof v === "number" && Number.isSafeInteger(v);
    case "null":
      return v === null;
    case "enum":
      return typeof v === "string" && s.values.includes(v);
    case "array":
      return Array.isArray(v) && v.every((x: unknown) => fitsSchema(s.items, x));
    case "nullable":
      return v === null || fitsSchema(s.inner, v);
    case "object": {
      if (!isPlainObject(v)) {
        return false;
      }
      for (const k of Object.keys(v)) {
        if (!hasOwn(s.fields, k)) {
          return false;
        }
      }
      for (const [k, f] of Object.entries(s.fields)) {
        if (hasOwn(v, k) ? !fitsSchema(f.schema, v[k]) : !f.optional) {
          return false;
        }
      }
      return true;
    }
  }
}

/** One structural validator per entry of `SCHEMAS`, by operation name. */
export const VALIDATORS: Readonly<Record<string, (v: unknown) => boolean>> = Object.freeze(
  Object.fromEntries(Object.entries(SCHEMAS).map(([name, s]) => [name, (v: unknown): boolean => fitsSchema(s, v)])),
);
"#;

/// The fixed part after the operation table: lookups and the structural
/// validators for the JSON bodies the API core returns (design section
/// 3.7). Each validator refuses members it does not know, as the server's
/// decoders do.
const TAIL: &str = r#"
/** The operation named `name`. */
export function operation(name: OpName): Operation {
  for (const op of OPERATIONS) {
    if (op.name === name) {
      return op;
    }
  }
  throw new Error("unknown operation");
}

/** Whether `v` names an operation of the registry. */
export function isOpName(v: unknown): v is OpName {
  return typeof v === "string" && (OP_NAMES as readonly string[]).includes(v);
}

/** Whether `v` is an object parsed from JSON, not null and not an array. */
function isRecord(v: unknown): v is Readonly<Record<string, unknown>> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Whether every member of `v` is one of `allowed`. */
function onlyMembers(v: Readonly<Record<string, unknown>>, allowed: readonly string[]): boolean {
  for (const k of Object.keys(v)) {
    if (!allowed.includes(k)) {
      return false;
    }
  }
  return true;
}

/**
 * A refusal: a stable code and the rule text, never an account. `values`
 * holds the values the rule names, by parameter id, such as P-05 and P-58
 * of I-50 at save (M4 design section 15.0).
 */
export interface ApiErrorBody {
  readonly code: string;
  readonly rule?: string;
  readonly values?: Readonly<Record<string, string>>;
}

/** Whether `v` is an `ApiErrorBody`, with no other member. */
export function isApiErrorBody(v: unknown): v is ApiErrorBody {
  if (!isRecord(v) || !onlyMembers(v, ["code", "rule", "values"])) {
    return false;
  }
  if (typeof v["code"] !== "string") {
    return false;
  }
  if ("rule" in v && typeof v["rule"] !== "string") {
    return false;
  }
  const values = v["values"];
  return !("values" in v) || (isRecord(values) && Object.values(values).every((x) => typeof x === "string"));
}

/** A call that became a pending action for a confirmation in the platform (I-85). */
export interface PendingReceipt {
  readonly status: "awaiting_confirmation";
  readonly confirm_path: string;
  readonly expires: string;
}

/** Whether `v` is a `PendingReceipt`, with no other member. */
export function isPendingReceipt(v: unknown): v is PendingReceipt {
  if (!isRecord(v) || !onlyMembers(v, ["status", "confirm_path", "expires"])) {
    return false;
  }
  return (
    v["status"] === "awaiting_confirmation" &&
    typeof v["confirm_path"] === "string" &&
    typeof v["expires"] === "string"
  );
}
"#;

/// A TypeScript string literal of `s`, in double quotes.
pub(crate) fn ts_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len().saturating_add(2));
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if c.is_ascii_graphic() || c == ' ' => out.push(c),
            c => out.push_str(&format!("\\u{{{:x}}}", u32::from(c))),
        }
    }
    out.push('"');
    out
}

fn method(m: Method) -> &'static str {
    m.as_str()
}

fn classification(c: Classification) -> &'static str {
    c.as_str()
}

fn session(s: SessionNeed) -> &'static str {
    s.as_str()
}

/// A union type of string literals, one per line.
fn union(name: &str, doc: &str, members: &[String]) -> String {
    let mut out = format!("/** {doc} */\nexport type {name} =\n");
    for (i, m) in members.iter().enumerate() {
        let end = if i.saturating_add(1) == members.len() {
            ";"
        } else {
            ""
        };
        out.push_str(&format!("  | {m}{end}\n"));
    }
    if members.is_empty() {
        out.push_str("  never;\n");
    }
    out.push('\n');
    out
}

/// The route segments of `path`, as a TypeScript array literal.
fn segments(path: &str) -> String {
    let parts: Vec<String> = path
        .split('/')
        .filter(|s| !s.is_empty())
        .map(
            |s| match s.strip_prefix('{').and_then(|s| s.strip_suffix('}')) {
                Some(name) => format!("{{ kind: \"param\", name: {} }}", ts_str(name)),
                None => format!("{{ kind: \"literal\", text: {} }}", ts_str(s)),
            },
        )
        .collect();
    format!("[{}]", parts.join(", "))
}

/// The path parameters of `path`, as a TypeScript array literal.
fn params(path: &str) -> String {
    let names: Vec<String> = route_params(path).map(ts_str).collect();
    format!("[{}]", names.join(", "))
}

/// One entry of the operation table.
fn entry(op: &OpSpec) -> String {
    let (m, path) = op.route.unwrap_or((Method::Get, ""));
    let base = if path.starts_with("/p/") || path == "/p" {
        "page"
    } else {
        "api"
    };
    let tool = match op.tool {
        Some(t) => format!(
            "{{ name: {}, scope: {}, prepareOnly: {} }}",
            ts_str(t.name),
            match op.scope {
                Some(s) => ts_str(s.as_str()),
                None => "null".to_string(),
            },
            t.prepare_only
        ),
        None => "null".to_string(),
    };
    let body = !matches!(m, Method::Get);
    format!(
        "  {{\n    name: {},\n    method: {},\n    path: {},\n    base: {},\n    segments: {},\n    params: {},\n    body: {},\n    highRisk: {},\n    binding: {},\n    session: {},\n    classification: {},\n    tool: {},\n  }},\n",
        ts_str(op.name),
        ts_str(method(m)),
        ts_str(path),
        ts_str(base),
        segments(path),
        params(path),
        body,
        op.high_risk,
        op.binding,
        ts_str(session(op.session)),
        ts_str(classification(op.classification)),
        tool,
    )
}

/// The parameter record type of one operation.
fn param_type(op: &OpSpec) -> String {
    let path = op.route.map_or("", |(_, p)| p);
    let names: Vec<String> = route_params(path)
        .map(|n| format!("readonly {}: string", ts_str(n)))
        .collect();
    if names.is_empty() {
        "Readonly<Record<never, string>>".to_string()
    } else {
        format!("{{ {} }}", names.join("; "))
    }
}

/// `n` spaces.
fn pad(n: usize) -> String {
    " ".repeat(n)
}

/// The words a schema literal uses as its own keys.
const SCHEMA_KEYWORDS: [&str; 7] = [
    "kind", "values", "items", "inner", "fields", "schema", "optional",
];

/// The key of an object member in a schema literal. A member named like
/// a schema keyword, such as the `kind` of an assignment, is written as a
/// computed key, so a reader of the text never takes it for the keyword.
fn member_key(name: &str) -> String {
    if SCHEMA_KEYWORDS.contains(&name) {
        format!("[{}]", ts_str(name))
    } else {
        ts_str(name)
    }
}

/// The TypeScript literal of `s`. The first line carries no indentation,
/// and every later line is indented from `indent`.
fn shape(s: &Shape, indent: usize) -> String {
    let kind = ts_str(s.kind());
    match s {
        Shape::Enum(values) => {
            let values: Vec<String> = values.iter().map(|v| ts_str(v)).collect();
            format!("{{ kind: {kind}, values: [{}] }}", values.join(", "))
        }
        Shape::Array(items) => format!("{{ kind: {kind}, items: {} }}", shape(items, indent)),
        Shape::Nullable(inner) => format!("{{ kind: {kind}, inner: {} }}", shape(inner, indent)),
        Shape::Object(members) => {
            let inner = indent.saturating_add(2);
            let field = inner.saturating_add(2);
            let mut out = format!(
                "{{\n{}kind: {kind},\n{}fields: {{\n",
                pad(inner),
                pad(inner)
            );
            for m in *members {
                out.push_str(&format!(
                    "{}{}: {{ schema: {}, optional: {} }},\n",
                    pad(field),
                    member_key(m.name),
                    shape(&m.shape, field),
                    m.optional
                ));
            }
            out.push_str(&format!("{}}},\n{}}}", pad(inner), pad(indent)));
            out
        }
        _ => format!("{{ kind: {kind} }}"),
    }
}

/// The `SCHEMAS` table of `replies`, by operation name.
fn schemas(replies: &[(&str, Shape)]) -> String {
    let mut out = String::from(
        "\n/** The reply shape of each operation whose data the API core serves, by operation name. */\n",
    );
    out.push_str("export const SCHEMAS: Readonly<Record<string, Schema>> = {\n");
    for (name, s) in replies {
        out.push_str(&format!("  {}: {},\n", ts_str(name), shape(s, 2)));
    }
    out.push_str("};\n");
    out
}

/// The whole file for `ops` and their reply shapes `replies`.
pub(crate) fn render(ops: &[OpSpec], replies: &[(&str, Shape)]) -> String {
    let mut out = String::from(HEADER);
    out.push('\n');
    out.push_str(IMPORTS);
    out.push('\n');
    out.push_str("/** The prefix of every API route. */\n");
    out.push_str("export const API_PREFIX = \"/api/v1\";\n\n");
    out.push_str("/** An HTTP method of a web route. */\n");
    out.push_str("export type Method = \"GET\" | \"POST\" | \"PUT\" | \"DELETE\";\n\n");
    out.push_str("/** Where a route is served: under API_PREFIX, or as a public page. */\n");
    out.push_str("export type Base = \"api\" | \"page\";\n\n");
    out.push_str(&union(
        "Classification",
        "How an MCP response classifies its data.",
        &[
            Classification::Public,
            Classification::Confidential,
            Classification::Personal,
        ]
        .iter()
        .map(|c| ts_str(c.as_str()))
        .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "SessionNeed",
        "The session strength an operation needs (I-77).",
        &[SessionNeed::Any, SessionNeed::PhishingResistant]
            .iter()
            .map(|s| ts_str(s.as_str()))
            .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "Scope",
        "An OAuth scope issued in M4.",
        &Scope::ALL
            .iter()
            .map(|s| ts_str(s.as_str()))
            .collect::<Vec<_>>(),
    ));
    out.push_str(&union(
        "OpName",
        "The name of an operation of the registry.",
        &ops.iter().map(|o| ts_str(o.name)).collect::<Vec<_>>(),
    ));
    out.push_str(
        "/** One segment of a route: fixed text, or a named parameter. */\n\
         export type Segment =\n\
         \x20 | { readonly kind: \"literal\"; readonly text: string }\n\
         \x20 | { readonly kind: \"param\"; readonly name: string };\n\n",
    );
    out.push_str(
        "/** The MCP tool of an operation. Public tools need no scope. */\n\
         export interface Tool {\n\
         \x20 readonly name: string;\n\
         \x20 readonly scope: Scope | null;\n\
         \x20 readonly prepareOnly: boolean;\n\
         }\n\n",
    );
    out.push_str(
        "/** One operation of the registry, as the application sees it. */\n\
         export interface Operation {\n\
         \x20 readonly name: OpName;\n\
         \x20 readonly method: Method;\n\
         \x20 readonly path: string;\n\
         \x20 readonly base: Base;\n\
         \x20 readonly segments: readonly Segment[];\n\
         \x20 readonly params: readonly string[];\n\
         \x20 readonly body: boolean;\n\
         \x20 readonly highRisk: boolean;\n\
         \x20 readonly binding: boolean;\n\
         \x20 readonly session: SessionNeed;\n\
         \x20 readonly classification: Classification;\n\
         \x20 readonly tool: Tool | null;\n\
         }\n\n",
    );
    out.push_str("/** The path parameters of each operation, by name. */\n");
    out.push_str("export interface OpParams {\n");
    for op in ops {
        out.push_str(&format!(
            "  readonly {}: {};\n",
            ts_str(op.name),
            param_type(op)
        ));
    }
    out.push_str("}\n\n");
    out.push_str("/** Every operation name, in registry order. */\n");
    out.push_str("export const OP_NAMES: readonly OpName[] = [\n");
    for op in ops {
        out.push_str(&format!("  {},\n", ts_str(op.name)));
    }
    out.push_str("];\n\n");
    out.push_str("/** Every operation of the registry, in registry order. */\n");
    out.push_str("export const OPERATIONS: readonly Operation[] = [\n");
    for op in ops {
        out.push_str(&entry(op));
    }
    out.push_str("];\n");
    out.push_str(TAIL);
    out.push_str(SCHEMA_TYPES);
    out.push_str(&schemas(replies));
    out.push_str(VALIDATOR_TAIL);
    out
}
